    fun initializeScreenModel() {
        connectionState = ConnectionState.OnLoading
        screenModelScope.launch {
            try {
                val userToken = PreferenceManager.getUserToken()
                if (userToken == null) {
                    connectionState =
                        ConnectionState.OnFailure("You are not logged in, please login to continue")
                } else {
                    val res = ApiActions.getUserModelByEmail(
                        LogInModel(
                            userToken.email,
                            userToken.password
                        )
                    )
                    connectionState = ConnectionState.OnSucsess("")
                    userModel = res.data
                    if (transcribeJobModel != null) {
                        Logger.e { "4" }
                        ApiActionsWebsocket.connectToWebsocket(
                            transcribeJobModel!!.transcriptionId,
                            userModel?.apiKey!!,
                            onConnect = {
                                transcribeJobModel = it
                            }
                        )
                    }
                }
            } catch (_: Exception) {
                connectionState =
                    ConnectionState.OnFailure("You are not logged in, please login to continue")
            }
            authLogInModel = LogInModel(
                BuildConfig.AUTH_EMAIL,
                BuildConfig.AUTH_PASSWORD
            )
            playAudio(
                Res.readBytes("files/beep.mp3"),
                volume = bgVolume,
                mimeType = "audio/mp3",
                interaction = { audioController = it }
            )
        }
    }

    fun checkKimLanguages(lang: String) {
        if (lang.isBlank()) {
            _kimLanguages.clear()
            _kimLanguages.addAll(KimLanguage.entries.shuffled().take(5))
            return
        }
        // 1. Calculate the new data first
        val filtered = KimLanguage.entries
            .filter {
                val name = it.name.lowercase()
                name.contains(lang.lowercase(), ignoreCase = true)
            }
            .shuffled()
            .take(5)

        // 2. Update the existing SnapshotStateList
        _kimLanguages.clear()
        _kimLanguages.addAll(filtered)
    }

