    fun changeBgVolume(int: Int) {
        try {
            screenModelScope.launch {
                bgVolume = int.toDouble()
                audioController?.setVolume(int.toDouble() / 10)
                audioController?.stop()
                audioController?.play()
            }
        } catch (e: Exception) {
            Logger.e { "Can not play sound at this moment : $e" }
        }
    }

