    fun deleteJob(jobId: String) {
        screenModelScope.launch {
            runCatching {
                transcribingScreenPopup = PopupModel(
                    show = true,
                    title = "Delete Transcription",
                    description = "Deletion in progress please wait...",
                    content = { CircularProgressIndicator() }
                )
                ApiActions.deleteJobByJobId(
                    LogInModel(
                        userModel?.email ?: "",
                        userModel?.password ?: ""
                    ),
                    jobId
                )
            }.onSuccess { suc ->
                if (suc.data != null) transcribeJobModel = null
                transcribingScreenPopup = PopupModel(
                    show = true,
                    title = "Delete Process",
                    description = suc.message,
                    content = { Icon(TablerIcons.Check, null, tint = Color.Green) }
                )
            }.onFailure { error ->
                transcribingScreenPopup = PopupModel(
                    show = true,
                    title = "Error",
