package api.auth.kimdeo.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable


@Serializable
data class OnlySegment(
    @SerialName("text")
    val text: String,
    @SerialName("start")
    val start: Double,
    @SerialName("end")
    val end: Double,
) {
    companion object {
        fun empty(): OnlySegment = OnlySegment("", 0.0, 0.0)
    }
}


@Serializable
data class TranscriptionConfig(
    @SerialName("file_path")
    val filePath: String,
    @SerialName("language")
    val languageCode: String? = null,
    @SerialName("add_word_timestamp")
    val addWordTimestamp: Boolean = false,
    @SerialName("has_multilingual")
    val hasMultilingual: Boolean = false,
)


@Serializable
data class SegmentWord(
    @SerialName("word")
    val word: String,
    @SerialName("start")
    val start: Double,
    @SerialName("end")
    val end: Double,
)

@Serializable
data class Segment(
    @SerialName("text")
    val text: String,
    @SerialName("start")
    val start: Double,
    @SerialName("end")
    val end: Double,
    @SerialName("words")
    val words: List<SegmentWord>? = null,
)

@Serializable
data class TranscribeInfo(
    @SerialName("language")
    val languageCode: String,
    @SerialName("language_probability")
    val languageProbability: Double,
    @SerialName("duration")
    val duration: Double,
    @SerialName("file_path")
    val filePath: String,
)

@Serializable
data class Transcription(
    @SerialName("segments")
    val segments: List<Segment>,
    @SerialName("info")
    val transcribeInfo: TranscribeInfo,
) {
    fun getText(): String {
        return buildString {
            for (segment in segments) {
                append(segment.text)
            }
        }
    }

    fun getOnlySegments(): List<OnlySegment> {
        return buildList {
            for (segment in segments) {
                add(OnlySegment(text = segment.text, start = segment.start, end = segment.end))
            }
        }
    }
}


@Serializable
data class TTsConfigModel(
    @SerialName("segments")
    val segments: List<Segment>,
    @SerialName("language")
    val languageCode: String,
    @SerialName("bg_volume")
    val bgVolume: Double,
    @SerialName("video_path")
    val videoPath: String,
)


@Serializable
data class VoiceOverConfigModel(
    @SerialName("json_path")
    val jsonPath: String,
    @SerialName("language")
    val languageCode: String,
    @SerialName("bg_volume")
    val bgVolume: Double,
    @SerialName("video_path")
    val videoPath: String,
)