object AuthScreen : Screen {
    @Composable
    override fun Content() {
        val deviceInfo = rememberDeviceInfo()
        val screenModel = rememberScreenModel { AuthScreenModel() }
        val navigator = LocalNavigator.current
        Surface {
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                DisplayPopup(
                    show = screenModel.showPopup.show,
                    onDismiss = {
                        if (screenModel.showPopup.isDismissible) screenModel.showPopup =
                            PopupModel()
                    },
                    content = {
                        Column(
                            modifier = Modifier.padding(PixelDensity.EXTRA_LARGE).outline(
                                color = MaterialTheme.colorScheme.onBackground,
                                bgColor = MaterialTheme.colorScheme.background,
                                padding = PixelDensity.SMALL,
                                shape = MaterialTheme.shapes.small
                            ),
                            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                        ) {
                            HorizontalTextIcon(
                                leadingContent = screenModel.showPopup.content,
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                                text = screenModel.showPopup.title,
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                            Text(
                                text = screenModel.showPopup.description,
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        }
                    },
                )
                IconButton(
                    modifier = Modifier.align(Alignment.TopStart).padding(PixelDensity.SMALL),
                    onClick = {
                        navigator?.pop()
                    },
                    content = {
                        Icon(
                            TablerIcons.Backspace, null
                        )
                    })
                when (deviceInfo.orientation) {
                    Orientation.PORTRAIT -> {
                        AuthFormDisplay(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(PixelDensity.MEDIUM)
                                .verticalScrollable(),
                            screenModel = screenModel
                        )
                    }

                    else -> Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.Center,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        AuthFormDisplay(
                            modifier = Modifier
                                .width(
                                    PixelDensity.getPixelDensity(
                                        deviceInfo.width / 2
                                    )
                                ).padding(PixelDensity.MEDIUM)
                                .verticalScrollable(),
                            screenModel = screenModel
                        )
                        Spacer(
                            Modifier.requiredWidthIn(
                                PixelDensity.EXTRA_LARGE,
                                PixelDensity.getPixelDensity(200)
                            )
                        )
                        TestimonyDisplay(
                            modifier = Modifier
                                .width(
                                    PixelDensity.getPixelDensity(
                                        deviceInfo.width / 2
                                    )
                                ).padding(PixelDensity.MEDIUM)
                        )
                    }
                }
            }
        }
    }

    @Composable
    private fun AuthFormDisplay(modifier: Modifier, screenModel: AuthScreenModel) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth().horizontalScrollable(),
                horizontalArrangement = Arrangement.Center
            ) {
                TextButton(
                    modifier = Modifier.underlineIf(
                        condition = !screenModel.isSignUp,
                        color = MaterialTheme.colorScheme.primary,
                        defaultColor = MaterialTheme.colorScheme.onPrimary,
                        thickness = PixelDensity.VERY_SMALL
                    ),
                    enabled = screenModel.disableKey,
                    onClick = { screenModel.isSignUp = false },
                    colors = ButtonDefaults.textButtonColors(
                        contentColor = if (!screenModel.isSignUp) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.secondary
                    )
                ) {
                    Text(
                        modifier = Modifier.padding(horizontal = PixelDensity.LARGE),
                        text = "Sign In",
                        style = MaterialTheme.typography.headlineSmall
                    )
                }
                TextButton(
                    modifier = Modifier.underlineIf(
                        condition = screenModel.isSignUp,
                        color = MaterialTheme.colorScheme.primary,
                        defaultColor = MaterialTheme.colorScheme.onPrimary,
                        thickness = PixelDensity.VERY_SMALL
                    ),
                    enabled = screenModel.disableKey,
                    onClick = { screenModel.isSignUp = true },
                    colors = ButtonDefaults.textButtonColors(
                        contentColor = if (screenModel.isSignUp) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.secondary
                    )
                ) {
                    Text(
                        modifier = Modifier.padding(horizontal = PixelDensity.LARGE),
                        text = "Sign Up",
                        style = MaterialTheme.typography.headlineSmall
                    )
                }
            }
            AnimatedVisibility(!screenModel.isSignUp) {
                SignInForm(
                    modifier = Modifier.fillMaxWidth(),
                    screenModel = screenModel
                )
            }
            AnimatedVisibility(screenModel.isSignUp) {
                SignUpForm(
                    modifier = Modifier.fillMaxWidth(),
                    screenModel = screenModel
                )
            }
        }
    }

    @Composable
    private fun SignUpForm(modifier: Modifier, screenModel: AuthScreenModel) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Text("Create Account", style = MaterialTheme.typography.headlineMedium)
            Text(
                "Sign up to start using our AI transcription service",
                style = MaterialTheme.typography.bodyMedium
            )
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
            ) {
                OutlinedTextField(
                    isError = screenModel.firstName.isEmpty(),
                    modifier = Modifier.weight(1f),
                    label = {
                        Text(
                            "First Name",
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                        )
                    },
                    value = screenModel.firstName,
                    singleLine = true,
                    onValueChange = { screenModel.firstName = it },
                    placeholder = {
                        Text(
                            "John",
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        )
                    },
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Text,
                        capitalization = KeyboardCapitalization.Words
                    ),
                    leadingIcon = {
                        Icon(TablerIcons.UserX, null)
                    }
                )
                OutlinedTextField(
                    isError = screenModel.lastName.isEmpty(),
                    modifier = Modifier.weight(1f),
                    label = {
                        Text(
                            "Last Name",
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                        )
                    },
                    value = screenModel.lastName,
                    singleLine = true,
                    onValueChange = { screenModel.lastName = it },
                    placeholder = {
                        Text(
                            "Doe",
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        )
                    },
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Text,
                        capitalization = KeyboardCapitalization.Words
                    ),
                    leadingIcon = {
                        Icon(TablerIcons.UserX, null)
                    }
                )
            }
            OutlinedTextField(
                isError = screenModel.email.isEmpty(),
                modifier = Modifier.fillMaxWidth(),
                label = {
                    Text(
                        "Email",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                },
                value = screenModel.email,
                onValueChange = { screenModel.email = it },
                singleLine = true,
                placeholder = {
                    Text(
                        "your@email.com",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    )
                },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email),
                leadingIcon = {
                    Icon(TablerIcons.Mail, null)
                }
            )
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
            ) {
                OutlinedTextField(
                    isError = screenModel.password.isEmpty(),
                    modifier = Modifier.weight(1f),
                    value = screenModel.password,
                    singleLine = true,
                    onValueChange = { screenModel.password = it },
                    placeholder = {
                        Text(
                            "*******",
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        )
                    },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                    visualTransformation = if (screenModel.showPassword) VisualTransformation.None else PasswordVisualTransformation(),
                    leadingIcon = {
                        Icon(TablerIcons.Key, null)
                    },
                    trailingIcon = {
                        IconButton(onClick = {
                            screenModel.showPassword = !screenModel.showPassword
                        }) {
                            Icon(
                                if (screenModel.showPassword) TablerIcons.EyeOff else TablerIcons.Eye,
                                "toggle password visibility"
                            )
                        }
                    }
                )
                OutlinedTextField(
                    isError = screenModel.confirmPassword.isEmpty() || screenModel.password != screenModel.confirmPassword,
                    modifier = Modifier.weight(1f),
                    value = screenModel.confirmPassword,
                    singleLine = true,
                    onValueChange = { screenModel.confirmPassword = it },
                    placeholder = {
                        Text(
                            "*******",
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        )
                    },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                    visualTransformation = if (screenModel.showPassword) VisualTransformation.None else PasswordVisualTransformation(),
                    leadingIcon = {
                        Icon(TablerIcons.Key, null)
                    },
                    trailingIcon = {
                        IconButton(onClick = {
                            screenModel.showPassword = !screenModel.showPassword
                        }) {
                            Icon(
                                if (screenModel.showPassword) TablerIcons.EyeOff else TablerIcons.Eye,
                                "toggle password visibility"
                            )
                        }
                    }
                )
            }
            DisplayExpandableHorizontal(
                modifier = Modifier
                    .fillMaxWidth(07f)
                    .outline(
                        color = if (screenModel.selectCountry == null) Color.Red else MaterialTheme.colorScheme.primary
                    )
                    .padding(PixelDensity.MEDIUM),
                items = KimCountry.entries.toList(),
                content = {
                    HorizontalTextIcon(
                        leadingContent = {
                            Icon(TablerIcons.Map2, null)
                        },

                        text = buildString {
                            append("Select Your Country")
                            screenModel.selectCountry?.let {
                                append(
                                    " ( ${
                                        it.name.lowercase().replace("_", " ")
                                    } )"
                                )
                            }
                        },
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                },
                itemContent = { country ->
                    OutlinedButton(
                        onClick = { screenModel.selectCountry = country },
                        content = {
                            Text(
                                text = country.name.replace("_", " "),
                                style = MaterialTheme.typography.bodySmall.copy(fontWeight = FontWeight.Bold)
                            )
                        }
                    )
                },
            )
            Button(
                enabled = screenModel.disableKey,
                onClick = { screenModel.signUpClicked({ screenModel.isSignUp = false }) }) {
                Text(
                    "Create Account",
                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                )
            }

            ContactSupport()
        }
    }

    @Composable
    private fun SignInForm(modifier: Modifier, screenModel: AuthScreenModel) {
        val navigator = LocalNavigator.currentOrThrow
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Text("Welcome back", style = MaterialTheme.typography.headlineMedium)
            Text("Sign in to your account to continue", style = MaterialTheme.typography.bodyMedium)
            OutlinedTextField(
                isError = screenModel.email.isEmpty(),
                modifier = Modifier.fillMaxWidth(),
                label = {
                    Text(
                        "Email",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                },
                value = screenModel.email,
                singleLine = true,
                onValueChange = { screenModel.email = it },
                placeholder = {
                    Text(
                        "your@email.com",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    )
                },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email),
                leadingIcon = {
                    Icon(TablerIcons.Mail, null)
                }
            )
            OutlinedTextField(
                isError = screenModel.password.isEmpty(),
                modifier = Modifier.fillMaxWidth(),
                label = {
                    Text(
                        "Password",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                },
                value = screenModel.password,
                singleLine = true,
                onValueChange = { screenModel.password = it },
                placeholder = {
                    Text(
                        "*******",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    )
                },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                visualTransformation = if (screenModel.showPassword) VisualTransformation.None else PasswordVisualTransformation(),
                leadingIcon = {
                    Icon(TablerIcons.Key, null)
                },
                trailingIcon = {
                    IconButton(onClick = { screenModel.showPassword = !screenModel.showPassword }) {
                        Icon(
                            if (screenModel.showPassword) TablerIcons.EyeOff else TablerIcons.Eye,
                            "toggle password visibility"
                        )
                    }
                }
            )

            Button(enabled = screenModel.disableKey, onClick = {
                screenModel.signInClicked(
                    onSuccessful = {
                        try {
                            navigator.replaceAll(DashBoardScreen)
                        } catch (e: Exception) {
                            Logger.e { "signIn Failed: error" }
                        }
                    }
                )
            }) {
                Text(
                    "Sign In",
                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                )
            }
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                onClick = {
                    screenModel.signInWithGoogle {
                        navigator.replaceAll(DashBoardScreen)
                    }
                }
            ) {
                HorizontalTextIcon(
                    leadingContent = {
//                        GradientIcon(
//                            imageVector = TablerIcons.BrandGoogle,
//                        )
                        Icon(
                            painter = painterResource(Res.drawable.ic_google),
                            contentDescription = "Google Logo",
                            tint = Color.Unspecified, // Don't forget this, otherwise it turns into a solid block color!
                        )
                    },
                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                    text = "sign in with google",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
            ContactSupport()
        }
    }


