        Column(
            modifier = modifier,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            HorizontalTextIcon(
                leadingContent = { Icon(TablerIcons.Video, null) },
                text = "KimDeo",
                style = MaterialTheme.typography.headlineSmall.copy(fontWeight = FontWeight.Bold)
            )
            Text(
                text = "TranscribeAI Transform Audio & Video with AI",
                style = MaterialTheme.typography.headlineMedium.copy(fontWeight = FontWeight.Bold)
            )

            Text(
                text = "Join thousands of professionals who use our AI transcription service to save time and increase productivity.",
                style = MaterialTheme.typography.bodyMedium
            )
            ListItem(
                leadingContent = {
                    Icon(TablerIcons.Bolt, null)
                },
                headlineContent = {
                    Text(
                        text = "Fast & Accurate",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                },
                supportingContent = { Text(text = "Get transcriptions with up to 96% accuracy in minutes") }
            )
            ListItem(
                leadingContent = {
                    Icon(TablerIcons.Language, null)
                },
                headlineContent = {
                    Text(
                        text = "Multi-language Support",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                },
                supportingContent = { Text(text = "Transcribe in over 50 languages and dialects") }
            )
            ListItem(
                leadingContent = {
                    Icon(TablerIcons.Shield, null)
                },
                headlineContent = {
                    Text(
                        text = "Secure & Private",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                },
                supportingContent = { Text(text = "Your files are encrypted and never shared with third parties") }
            )
        }
    }
}