package api.auth.kimdeo.model

import kotlinx.serialization.ExperimentalSerializationApi
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonNames


@Serializable
data class UserModel(

    val userId: String = "",

    val imagePath: String = "",

    val firstName: String,

    val lastName: String,

    val email: String,
    val password: String,
    val role: String,

    val phoneNumber: String = "",

    val apiKey: String = "",

    val authToken: String = "",

    val dateOfBirth: String = "",

    val country: KimCountry,

    val metadata: UserMeterData = UserMeterData.empty(),

    val isActive: Boolean = false,

    val createdAt: Long = 0L,

    val updatedAt: Long = 0L
)

@Serializable data class UserToken(
    val email: String,
    val userId: String,
    val password: String
)

@Serializable
class UserMeterData {
    companion object {
        fun empty() = UserMeterData()
    }
}



@Serializable
data class RegistrationModel(
    @SerialName("first_name")
    val firstName: String,
    @SerialName("last_name")
    val lastName: String,
    @SerialName("email")
    val email: String,
    @SerialName("password")
    val password: String,
    @SerialName("country")
    val country: KimCountry
)


@Serializable
data class TokenModel(
    val accessToken: String,
    val refreshToken: String,
)
@OptIn(ExperimentalSerializationApi::class)
@Serializable
data class AuthUserModel<A>(
    @JsonNames("data", "userData")
    val userData: A? = null,
    val tokenData: TokenModel? = null,
    val message: String,
    val errorMessage: String = "",
    val status: Boolean
)


@Serializable
data class LogInModel(
    val emailOrUid: String,
    val password: String,
)