import compose.icons.tablericons.Trash


@Composable
fun SecurityDisplay(modifier: Modifier, screenModel: SettingScreenModel) {
    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        PasswordChangDisplay(
            modifier = Modifier.padding(PixelDensity.MEDIUM),
            screenModel = screenModel
        )
    }
}


@Composable
fun PasswordChangDisplay(modifier: Modifier, screenModel: SettingScreenModel) {
    val deviceInfo = rememberDeviceInfo()
    Surface(modifier = modifier, tonalElevation = PixelDensity.VERY_SMALL) {
        Column(
            modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
        ) {
            Text(
                text = "Change Password",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            HorizontalDivider()
            OutlinedTextField(
                modifier = Modifier.fillMaxWidth(),
                value = screenModel.currentPassword,
                onValueChange = { screenModel.currentPassword = it },
                placeholder = { Text(text = "Current Password") },
                textStyle = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
            )
            if (deviceInfo.orientation == Orientation.PORTRAIT){
                OutlinedTextField(
                    modifier = Modifier.fillMaxWidth(),
                    value = screenModel.newPassword,
                    onValueChange = { screenModel.newPassword = it },
                    placeholder = { Text(text = "New Password") },
                    textStyle = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                )
                OutlinedTextField(
                    modifier = Modifier.fillMaxWidth(),
                    value = screenModel.confirmNewPassword,
                    onValueChange = { screenModel.confirmNewPassword = it },
                    placeholder = { Text(text = "Confirm New Password") },
                    textStyle = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                )
            }else {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                ) {
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        value = screenModel.newPassword,
                        onValueChange = { screenModel.newPassword = it },
                        placeholder = { Text(text = "New Password") },
                        textStyle = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                    )
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        value = screenModel.confirmNewPassword,
                        onValueChange = { screenModel.confirmNewPassword = it },
                        placeholder = { Text(text = "Confirm New Password") },
                        textStyle = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                    )
                }
            }

            Button(onClick = {
                screenModel.showConfirmPopup(
                    ConfirmPopupModel(
                        show = true,
                        title = "Update Password",
                        description = "You are about to update your password. This action cannot be undone. If password is forgotten? Contact Support",
                        content = { ElevatedButton(onClick = { screenModel.changePassword() }) {} },
                        isDismissible = true
                    )
                )
            }) {
                Text(
                    text = "Update Password",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
        }
    }
}


@Composable
fun DeleteAccountDisplay(modifier: Modifier, screenModel: SettingScreenModel) {
    Surface(modifier = modifier) {
        Column(
            modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Text(
                text = "Danger Zone",
                style = MaterialTheme.typography.bodyLarge.copy(
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.error
                )
            )
            VerticalTextIcon(
                text = "Once you delete your account, this action is irreversible. All associated data will be permanently deleted and cannot be recovered.",
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                trailingContent = {
                    Button(
                        modifier = Modifier.fillMaxWidth(),
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error),
                        onClick = {
//                            screenModel.confirmPopupTypeChange(ConfirmationPopupType.DELETE_ACCOUNT)
                            screenModel.showConfirmPopup(
                                ConfirmPopupModel(
                                    show = true,
                                    title = "Delete Account",
                                    description = "Are you sure you want to delete your account? This action cannot be undone and all your data will be permanently deleted.",
                                    content = {
                                        ElevatedButton(onClick = { screenModel.deleteYourAccount() }) {
                                            HorizontalTextIcon(leadingContent = {
                                                Icon(TablerIcons.Trash, null)
                                            }, text = "Delete Account")
                                        }
                                    },
                                    isDismissible = true
                                )
                            )
                        }) { Text(text = "Delete Account") }
                }
            )
        }
    }
}

