package api.auth.kimdeo.screens.dashbord

import androidx.compose.material3.Icon
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.compose.ui.graphics.Color
import api.auth.kimdeo.core.PreferenceManager
import api.auth.kimdeo.core.api.ApiActions
import api.auth.kimdeo.model.ConnectionState
import api.auth.kimdeo.model.LogInModel
import api.auth.kimdeo.model.PopupModel
import api.auth.kimdeo.model.UserModel
import api.auth.kimdeo.utils.cleanError
import cafe.adriel.voyager.core.model.ScreenModel
import cafe.adriel.voyager.core.model.screenModelScope
import compose.icons.TablerIcons
import compose.icons.tablericons.AlertTriangle
import kotlinx.coroutines.launch


class DashBoardScreenModel : ScreenModel {
    var dashBoardPopup by mutableStateOf(PopupModel())
    var connectionState by mutableStateOf<ConnectionState>(ConnectionState.None)
        private set
    var userModel by mutableStateOf<UserModel?>(null)

    fun initialiseDashboard() {
        screenModelScope.launch {
            connectionState = ConnectionState.OnLoading
            runCatching {
                val ut = PreferenceManager.getUserToken()
                if (ut == null) {
                    connectionState =
                        ConnectionState.OnFailure("Can not get user at this time. Please try logging in.")
                    return@launch
                }
                val logInModel = LogInModel(
                    emailOrUid = ut.userId,
                    password = ut.password
                )
                ApiActions.getUserModelByEmail(logInModel)
            }
                .onSuccess { result ->
                    userModel = result.data
                    if (userModel == null) {
                        connectionState =
                            ConnectionState.OnFailure("Can not get user at this time. Please try logging in.")
                        dashBoardPopup = PopupModel(
                            show = true,
                            title = "Authenticating User",
                            description = cleanError(
                                result.message,
                                "Can not get user at this time. Please try logging in."
                            ),
                            content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) },
                            isDismissible = true
                        )
                    }
                    connectionState = ConnectionState.OnSucsess("")
                    return@launch
                }
                .onFailure { error ->
                    connectionState =
                        ConnectionState.OnFailure("Can not get user at this time. Please try logging in.")
                    dashBoardPopup = PopupModel(
                        show = true,
                        title = "Authenticating Error",
                        description = cleanError(
                            error.message,
                            "Can not get user at this time. Please try logging in."
                        ),
                        content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) },
                        isDismissible = true
                    )
                    return@launch
                }
            connectionState = ConnectionState.OnSucsess("")
        }
    }

}