class TranscribeScreen(private val transcribeJobModel: TranscribeJobModel? = null) : Screen {
    @Composable
    override fun Content() {
        val deviceInfo = rememberDeviceInfo()
        val screenModel = rememberScreenModel { TranscriptionScreenModel(transcribeJobModel) }
        val navigator = LocalNavigator.currentOrThrow
        Scaffold { pv ->
            DisplayToast(
                show = screenModel.toastPopup.show,
                onDismiss = { screenModel.toastPopup = PopupModel() },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { screenModel.transcribingScreenPopup.content() },
                        text = screenModel.transcribingScreenPopup.description,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                    )
                }
            )
            DisplayPopup(
                show = screenModel.transcribingScreenPopup.show,
                onDismiss = { screenModel.updateTranscribeScreenPopup(PopupModel()) },
                content = {
                    Column(
                        modifier = Modifier.background(color = MaterialTheme.colorScheme.onBackground)
                            .padding(
                                PixelDensity.MEDIUM
                            ), verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                    ) {
                        HorizontalTextIcon(
                            leadingContent = { screenModel.transcribingScreenPopup.content() },
                            text = screenModel.transcribingScreenPopup.title,
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.background
                            )
                        )
                        Text(
                            text = screenModel.transcribingScreenPopup.description,
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.background
                            )
                        )
                    }
                }
            )

            when (screenModel.connectionState) {
                is ConnectionState.OnSucsess -> {
                    when (deviceInfo.orientation) {
                        Orientation.PORTRAIT -> PortraitDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize(),
                            deviceInfo = deviceInfo,
                            screenModel = screenModel
                        )

                        else -> LandScapeDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize()
                                .padding(PixelDensity.MEDIUM),
                            deviceInfo = deviceInfo,
                            screenModel = screenModel
                        )
                    }

                }

                is ConnectionState.OnFailure -> {
                    when (deviceInfo.orientation) {
                        Orientation.PORTRAIT -> PortraitDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize(),
                            deviceInfo = deviceInfo,
                            screenModel = screenModel
                        )

                        else -> LandScapeDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize()
                                .padding(PixelDensity.MEDIUM),
                            deviceInfo = deviceInfo,
                            screenModel = screenModel
                        )
                    }
                }

                else -> {
                    Column(
                        Modifier.fillMaxSize().padding(pv),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        val pulseBeforeShow = remember { mutableStateOf(false) }

                        LaunchedEffect(pulseBeforeShow) {
                            if (!pulseBeforeShow.value) {
                                delay(5000.milliseconds)
                                pulseBeforeShow.value = true
                            }
                        }
                        PulsingRing()
                        if (pulseBeforeShow.value) {
                            ShimmeringText(
                                "Loading... seems to be taking a lot of time.",
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                            )
                            ReloadButton(
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                                onReload = {
                                    screenModel.initializeScreenModel()

                                    pulseBeforeShow.value = false
                                },
                                onGoBack = { navigator.replace(DashBoardScreen) }
                            )
                        }
                    }
                }
            }

        }
    }

    @Composable
    private fun LandScapeDisplay(
        modifier: Modifier,
        deviceInfo: DeviceInfo,
        screenModel: TranscriptionScreenModel
    ) {
        SideDrawerBarLandscape(
            imagUrlString = screenModel.userModel?.imagePath ?: "",
            currentScreenType = ScreenType.TRANSCRIBING,
            drawerModifier = Modifier
                .width(PixelDensity.getPixelDensity(deviceInfo.width.toPercentage(20)))
                .fillMaxHeight(),
            modifier = modifier,
            isSignIn = screenModel.userModel != null,
            content = {
                Row(
                    modifier = Modifier.fillMaxSize()
                        .padding(PixelDensity.VERY_SMALL)
                        .padding(PixelDensity.MEDIUM),
                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                ) {
                    TranscriptionConfigurationDisplay(
                        modifier = Modifier.weight(1f).verticalScrollable(),
                    )
                    TranscriptionDisplay(
                        modifier = Modifier.weight(1f),
                    )
                }
            })
    }

    @Composable
    private fun PortraitDisplay(
        modifier: Modifier,
        deviceInfo: DeviceInfo,
        screenModel: TranscriptionScreenModel
    ) {
        Box(contentAlignment = Alignment.BottomCenter) {
            SideDrawerBarPortrait(
                modifier = Modifier
                    .width(PixelDensity.getPixelDensity(deviceInfo.width.toPercentage(70)))
                    .fillMaxHeight(),
                imagUrlString = screenModel.userModel?.imagePath ?: "",
                isSignIn = screenModel.userModel != null,
                currentScreenType = ScreenType.TRANSCRIBING,
                content = {
                    TranscriptionConfigurationDisplay(
                        modifier = modifier
                            .padding(PixelDensity.MEDIUM)
                            .verticalScrollable(),
                    )
                }
            )
            DisplayBottomSheet(
                sheetContent = { TranscriptionDisplay(modifier = Modifier.fillMaxWidth()) },
                anchorContent = {
                    if (screenModel.transcribeJobModel != null) {
                        Box(
                            Modifier
                                .displayShimmer(
                                    listOf(
                                        MaterialTheme.colorScheme.tertiary,
                                        MaterialTheme.colorScheme.onTertiary
                                    ),
                                    3000
                                ).height(PixelDensity.MEDIUM)
                        )
                    } else {
                        HorizontalDivider(thickness = PixelDensity.MEDIUM)
                    }
                },

                )
        }
    }


    @Composable
    private fun TranscriptionConfigurationDisplay(modifier: Modifier) {
        val screenModel = rememberScreenModel { TranscriptionScreenModel() }
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            SelectFileDisplay(modifier = Modifier.fillMaxWidth(), screenModel = screenModel)
            SetConfiguration(
                modifier = Modifier.fillMaxWidth().outline(),
                screenModel = screenModel
            )

            FlowRow(
                modifier = Modifier.fillMaxWidth().outline(),
                horizontalArrangement = Arrangement.spacedBy(PixelDensity.LARGE),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                content = {
                    Button(
                        modifier = Modifier.weight(1f),
                        enabled = screenModel.canGenerate,
                        onClick = { screenModel.transcribeMediaFile() }) {
                        HorizontalTextIcon(
                            leadingContent = { Icon(TablerIcons.Upload, null) },
                            text = "Start Transcription",
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        )
                    }
                    Button(
                        modifier = Modifier.weight(1f),
                        enabled = screenModel.canGenerate,
                        onClick = { screenModel.generateAudioFile() }) {
                        HorizontalTextIcon(
                            leadingContent = { Icon(TablerIcons.Upload, null) },
                            text = "Generate Audio File",
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        )
                    }
                    Button(
                        modifier = Modifier.weight(1f),
//                        enabled = screenModel.canStart == CanStart.TRANSCRIBE,
                        enabled = screenModel.canGenerate,
                        onClick = { screenModel.generateVoiceOverFile() }) {
                        HorizontalTextIcon(
                            leadingContent = { Icon(TablerIcons.Upload, null) },
                            text = "Generate Voice Over",
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        )
                    }
                }
            )
        }
    }


    @Composable
    private fun SetConfiguration(modifier: Modifier, screenModel: TranscriptionScreenModel) {
        val showConfig = remember { mutableStateOf(false) }
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
        ) {
            HorizontalTextIcon(
                modifier = Modifier
                    .clickable(onClick = { showConfig.value = !showConfig.value })
                    .padding(horizontal = PixelDensity.MEDIUM, vertical = PixelDensity.SMALL),
                trailingContent = {
                    Icon(
                        if (showConfig.value) TablerIcons.ChevronUp else TablerIcons.ChevronDown,
                        null
                    )
                },
                text = "Configure ${FileType.getFileType(screenModel.platformFile?.name).value} File",
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
            )
            HorizontalDivider()
            AnimatedVisibility(visible = showConfig.value) {
                Column(
                    Modifier.fillMaxWidth()
                        .padding(
                            top = PixelDensity.MEDIUM,
                            start = PixelDensity.MEDIUM,
                            end = PixelDensity.MEDIUM,
                            bottom = PixelDensity.VERY_SMALL
                        ),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                ) {
                    MultiplatformVolumeSelector(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(PixelDensity.SMALL),
                        currentVolume = screenModel.bgVolume.toInt(),
                        onVolumeChanged = { screenModel.changeBgVolume(it) }
                    )
                    SelectKimLanguage(screenModel)
                }
            }
        }
    }


    @Composable
    private fun SelectKimLanguage(screenModel: TranscriptionScreenModel) {
        var selectedKimLanguage by remember { mutableStateOf("") }
        var expandLanguage by remember { mutableStateOf(false) }
        Column(
            modifier = Modifier.outline(
                color = MaterialTheme.colorScheme.onBackground,
                padding = PixelDensity.SMALL
            ),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
        ) {
            HorizontalTextIcon(
                modifier = Modifier.clickable(onClick = { expandLanguage = !expandLanguage }),
                text = "language (${screenModel.kimLanguage})",
                style = MaterialTheme.typography.bodyMedium.copy(
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                ),
                horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                leadingContent = {
                    Icon(
                        imageVector = TablerIcons.Language,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.tertiary
                    )
                },
                trailingContent = {
                    Icon(
                        if (expandLanguage) TablerIcons.ChevronUp else TablerIcons.ChevronDown,
                        contentDescription = "expand languages"
                    )
                }
            )
            AnimatedVisibility(expandLanguage) {
                Column {
                    TextField(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = PixelDensity.SMALL)
                            .clip(MaterialTheme.shapes.medium),

                        value = selectedKimLanguage,
                        onValueChange = {
                            selectedKimLanguage = it
                            screenModel.checkKimLanguages(it)
                        },
                        textStyle = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        ),
                        placeholder = {
                            Text("Search language...")
                        },

                        singleLine = true,

                        leadingIcon = {
                            Icon(
                                imageVector = TablerIcons.Search,
                                contentDescription = "Search"
                            )
                        },

                        trailingIcon = {
                            if (selectedKimLanguage.isNotEmpty()) {
                                IconButton(onClick = {
                                    selectedKimLanguage = ""
                                    screenModel.checkKimLanguages("")
                                }) {
                                    Icon(
                                        imageVector = TablerIcons.ClearAll,
                                        contentDescription = "Clear"
                                    )
                                }
                            }
                        },

                        shape = MaterialTheme.shapes.medium,

                        colors = TextFieldDefaults.colors(
                            focusedContainerColor = MaterialTheme.colorScheme.surface,
                            unfocusedContainerColor = MaterialTheme.colorScheme.surfaceVariant,
                            focusedIndicatorColor = MaterialTheme.colorScheme.primary,
                            unfocusedIndicatorColor = MaterialTheme.colorScheme.outline,
                            cursorColor = MaterialTheme.colorScheme.primary
                        )
                    )

                    FlowRow(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        maxItemsInEachRow = 3,
                    ) {
                        screenModel.kimLanguages.forEach { item ->

                            val isSelected = screenModel.kimLanguage == item
                            item.codeCountry

                            Surface(
                                modifier = Modifier
                                    .padding(PixelDensity.SMALL)
                                    .clip(MaterialTheme.shapes.medium)
                                    .clickable {
                                        screenModel.kimLanguage = item
                                        expandLanguage = !expandLanguage
                                    },
                                shape = MaterialTheme.shapes.medium,
                                color = if (isSelected)
                                    MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                                else
                                    MaterialTheme.colorScheme.surfaceVariant,
                                tonalElevation = if (isSelected) 4.dp else 1.dp,
                                border = BorderStroke(
                                    width = 1.dp,
                                    color = if (isSelected)
                                        MaterialTheme.colorScheme.primary
                                    else
                                        MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)
                                )
                            ) {
                                Row(
                                    modifier = Modifier.padding(PixelDensity.SMALL),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                                ) {
                                    SubcomposeAsyncImage(
                                        model = KimLanguage.getCountryImageUrl(item.codeCountry),
                                        contentDescription = "country image",
                                        loading = {
                                            CircularProgressIndicator(
                                                Modifier.size(
                                                    PixelDensity.LARGE
                                                )
                                            )
                                        },
                                        error = { Icon(TablerIcons.World, null) }
                                    )

                                    Column(
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text(
                                            text = item.name.replaceFirstChar {
                                                if (it.isLowerCase()) it.titlecase() else it.toString()
                                            },
                                            style = MaterialTheme.typography.bodySmall.copy(
                                                fontWeight = FontWeight.SemiBold
                                            ),
                                            color = if (isSelected)
                                                MaterialTheme.colorScheme.primary
                                            else
                                                MaterialTheme.colorScheme.onSurface
                                        )

                                        Spacer(modifier = Modifier.height(2.dp))

                                        Text(
                                            text = item.codeCountry.uppercase(),
                                            style = MaterialTheme.typography.labelSmall,
                                            color = if (isSelected)
                                                MaterialTheme.colorScheme.primary
                                            else
                                                MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                    }
                                }
                            }
                        }
                        Text(
                            modifier = Modifier
                                .padding(horizontal = PixelDensity.LARGE)
                                .outline(
                                    width = PixelDensity.VERY_SMALL,
                                    padding = PixelDensity.SMALL
                                ),
                            text = "...",
                            style = MaterialTheme.typography.headlineMedium
                        )
                    }
                }
            }
        }
    }


    @Composable
    private fun SelectFileDisplay(
        modifier: Modifier,
        screenModel: TranscriptionScreenModel
    ) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .outline()
                    .clickable(onClick = { screenModel.getMediaFile() }),
                contentAlignment = Alignment.CenterStart
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Image(
                        modifier = Modifier.size(
                            width = PixelDensity.getPixelDensity(70),
                            height = PixelDensity.getPixelDensity(100)
                        ),
                        painter = when (FileType.getFileType(screenModel.platformFile?.name)) {
                            FileType.AUDIO -> painterResource(Res.drawable.audio)
                            FileType.VIDEO -> painterResource(Res.drawable.video)
                            FileType.NONE -> painterResource(Res.drawable.folders)
                        }, contentDescription = null
                    )
                    if (screenModel.platformFile == null) {
                        Text(
                            text = "Supports MP3, WAV, MP4, AVI, and more. Max file size 200MB.",
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                        )
                    } else {
                        Column {
                            StyledText(
                                contents = listOf(
                                    ComTextModel(
                                        text = Tools.convertLongToReadableSize(
                                            screenModel.platformFile?.size() ?: 0
                                        ),
                                        style = MaterialTheme.typography.headlineSmall.copy(
                                            color = MaterialTheme.colorScheme.tertiary
                                        ).toSpanStyle()
                                    ),
                                    ComTextModel(
                                        text = screenModel.platformFile?.name ?: "Unknown File",
                                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                            .toSpanStyle()
                                    )
                                )
                            )
                            Text(
                                text = screenModel.transcribeProcess.second,
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                            )
//                            if (screenModel.transcribeProcess.second.isNotEmpty()) {
//                            }
                        }
                    }
                }
            }
            AnimatedVisibility((screenModel.fileUploadState is FileConnectionState.OnGotten)) {
                HorizontalTextIcon(
                    modifier = Modifier
                        .outline()
                        .clickable(onClick = { screenModel.uploadCreateJob() })
                        .padding(horizontal = PixelDensity.MEDIUM, vertical = PixelDensity.SMALL),
                    leadingContent = { Icon(TablerIcons.CloudUpload, null) },
                    text = "Upload and Prepare",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
        }
    }


    @Composable
    private fun TranscriptionDisplay(modifier: Modifier) {
        val screenModel = rememberScreenModel { TranscriptionScreenModel() }
        Surface(modifier = modifier) {
            Column(Modifier.fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally) {
                val aj = remember(screenModel.transcribeJobModel) { screenModel.transcribeJobModel }
                if (aj == null) {
                    Box(
                        Modifier.fillMaxWidth()
                            .displayShimmer(
                                speed = 2000,
                                colors = listOf(
                                    MaterialTheme.colorScheme.tertiary,
                                    MaterialTheme.colorScheme.onTertiary,
                                )
                            ).padding(PixelDensity.EXTRA_LARGE),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "No Transcription Available",
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.inversePrimary
                            )
                        )
                    }
                } else {
                    ElevatedCard(
                        modifier = Modifier.padding(PixelDensity.MEDIUM),
                    ) {
                        Column(
                            modifier = Modifier.outline().fillMaxWidth(),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            HorizontalTextIcon(
                                leadingContent = {
                                    when (aj.jobStatus) {
                                        JobStatus.COMPLETED -> Icon(
                                            TablerIcons.Check,
                                            null,
                                            tint = Color.Green
                                        )

                                        JobStatus.FAILED -> Icon(
                                            TablerIcons.AlertTriangle,
                                            null,
                                            tint = Color.Red
                                        )

                                        JobStatus.QUEUED -> Icon(
                                            TablerIcons.FileCheck,
                                            null,
                                            tint = Color.Blue
                                        )

                                        JobStatus.PROCESSING -> CircularProgressIndicator(
                                            Modifier.size(
                                                PixelDensity.LARGE
                                            )
                                        )
                                    }
                                },
                                text = when (aj.jobStatus) {
                                    JobStatus.QUEUED -> "Media file processing please wait ..."
                                    JobStatus.PROCESSING -> "Your Media file is been prepared please wait ..."
                                    JobStatus.COMPLETED -> "${
                                        aj.filePath.fileNameWithoutExtension()
                                    } is ready for Transcription"

                                    JobStatus.FAILED -> "There was an error preparing your file"
                                },
                                maxLines = 2,
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                            HorizontalTextIcon(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(
                                        if (aj.jobStatus == JobStatus.COMPLETED) Color.Green
                                        else if (aj.jobStatus == JobStatus.FAILED) Color.Red
                                        else Color.Cyan,
                                        shape = MaterialTheme.shapes.small
                                    )
                                    .padding(PixelDensity.MEDIUM),
                                leadingContent = {
                                    Icon(
                                        if (JobStatus.COMPLETED == aj.jobStatus) TablerIcons.Check
                                        else if (JobStatus.FAILED == aj.jobStatus) TablerIcons.AlertTriangle
                                        else TablerIcons.Dots,
                                        null,
                                    )
                                },
                                text = aj.jobStatus.name,
                                style = MaterialTheme.typography.bodyMedium.copy(
                                    color = MaterialTheme.colorScheme.primary,
                                    fontWeight = FontWeight.Bold
                                )
                            )
                            StyledText(
                                contents = listOf(
                                    ComTextModel(
                                        text = "${aj.createdAt.toReadableDate().first} ",
                                        style = MaterialTheme.typography.bodyMedium.copy(
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.primary
                                        ).toSpanStyle()
                                    ), ComTextModel(
                                        text = "${aj.createdAt.toReadableDate().second} ",
                                        style = MaterialTheme.typography.bodyMedium.copy(
                                            fontWeight = FontWeight.SemiBold,
                                            color = MaterialTheme.colorScheme.primary
                                        ).toSpanStyle()
                                    )
                                )
                            )
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                            ) {
                                val suc =
                                    remember(aj.jobStatus) { aj.jobStatus == JobStatus.COMPLETED }
                                if (suc && !aj.outputSubtitlePath.isNullOrEmpty()) {
                                    TextButton(
                                        modifier = Modifier.weight(1f),
                                        onClick = {
                                            screenModel.downloadTextFile(aj.outputSubtitlePath)
                                        }) {
                                        Text(
                                            text = "Download subtitle",
                                            style = MaterialTheme.typography.bodyMedium.copy(
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                }
                                if (suc && !aj.outputAudioPath.isNullOrEmpty()) {
                                    TextButton(
                                        modifier = Modifier.weight(1f),
                                        onClick = {
                                            screenModel.downloadAudio(aj.outputAudioPath)
                                        }) {
                                        Text(
                                            text = "Download audio",
                                            style = MaterialTheme.typography.bodyMedium.copy(
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                }
                                if (suc && !aj.outputVideoPath.isNullOrEmpty()) {
                                    TextButton(
                                        modifier = Modifier.weight(1f),
                                        onClick = { screenModel.downloadVoiceOver(aj.outputVideoPath) }) {
                                        Text(
                                            text = "Download voice over",
                                            style = MaterialTheme.typography.bodyMedium.copy(
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    @Composable
    private fun MultiplatformVolumeSelector(
        modifier: Modifier = Modifier,
        currentVolume: Int,
        onVolumeChanged: (Int) -> Unit
    ) {
        Column(modifier) {
            Text("Volume: $currentVolume%")

            Slider(
                value = currentVolume.toFloat(),
                onValueChange = {
                    onVolumeChanged(it.roundToInt())
                },
                valueRange = 0f..10f
            )
        }
    }
}