@Composable
fun SideDrawerBarLandscape(
    modifier: Modifier,
    drawerModifier: Modifier,
    imagUrlString: String,
    isSignIn: Boolean,
    currentScreenType: ScreenType,
    content: @Composable RowScope.() -> Unit,
) {
    val navigator = LocalNavigator.currentOrThrow
    val rootNavigator = remember(navigator) {
        var n = navigator
        while (n.parent != null) n = n.parent!!
        n
    }
    Row(modifier) {
        Surface(tonalElevation = PixelDensity.VERY_SMALL) {
            @Composable
            fun navModifier(type: ScreenType) =
                if (currentScreenType == type) {
                    Modifier
                        .padding(PixelDensity.VERY_SMALL)
                        .outline()
                } else {
                    Modifier.padding(PixelDensity.VERY_SMALL)
                }
            Column(
                modifier = drawerModifier,
                verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
            ) {
                Column(
                    modifier = Modifier.weight(1f).verticalScrollable(),
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                ) {
                    VerticalTextIcon(
                        modifier = Modifier.padding(horizontal = PixelDensity.LARGE),
                        leadingContent = {
                            SubcomposeAsyncImage(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(PixelDensity.getPixelDensity(200))
                                    .clip(MaterialTheme.shapes.medium),
                                model = imagUrlString,//use profile image
                                contentDescription = "profile image",
                                loading = {
                                    DisplayLottie(
                                        modifier = Modifier,
                                        lottiePath = "files/avatar.json"
                                    )
                                },
                                error = {
                                    DisplayLottie(
                                        modifier = Modifier,
                                        lottiePath = "files/avatar.json"
                                    )
                                },
                            )
                        },
                        text = "KimDeo AI",
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                        style = MaterialTheme.typography.headlineSmall
                    )
                    HorizontalDivider()
                    HorizontalTextIcon(
                        modifier = navModifier(ScreenType.DASHBOARD)
                            .fillMaxWidth()
                            .clickable(onClick = { rootNavigator.replace(DashBoardScreen) })
                            .align(Alignment.CenterHorizontally)
                            .padding(PixelDensity.SMALL),
                        text = "Dashboard",
                        style = MaterialTheme.typography.bodyLarge,
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                        leadingContent = { Icon(TablerIcons.SmartHome, null) }
                    )
                    if (isSignIn) {
                        HorizontalTextIcon(
                            modifier = navModifier(ScreenType.PROFILE)
                                .fillMaxWidth()
                                .clickable(onClick = { rootNavigator.replace(ProfileUserScreen) })
                                .align(Alignment.CenterHorizontally)
                                .padding(PixelDensity.SMALL),
                            text = "Profile",
                            style = MaterialTheme.typography.bodyLarge,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            leadingContent = { Icon(TablerIcons.UserX, null) }
                        )
                    }
                    HorizontalTextIcon(
                        modifier = navModifier(ScreenType.VIDEO_PLAYER)
                            .fillMaxWidth()
                            .clickable(onClick = { rootNavigator.replace(BaseVideoPlayer()) })
                            .align(Alignment.CenterHorizontally)
                            .padding(PixelDensity.SMALL),
                        text = "Video Player",
                        style = MaterialTheme.typography.bodyLarge,
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                        leadingContent = { Icon(TablerIcons.Video, null) }
                    )
                    HorizontalTextIcon(
                        modifier = navModifier(ScreenType.TRANSCRIBING)
                            .fillMaxWidth()
                            .clickable(onClick = { rootNavigator.replace(TranscribeScreen()) })
                            .align(Alignment.CenterHorizontally)
                            .padding(PixelDensity.SMALL),
                        text = "Transcribing",
                        style = MaterialTheme.typography.bodyLarge,
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                        leadingContent = { Icon(TablerIcons.Settings, null) }
                    )
                    if (isSignIn) {
                        HorizontalTextIcon(
                            modifier = navModifier(ScreenType.SETTINGS)
                                .fillMaxWidth()
                                .clickable(onClick = { rootNavigator.replace(UserSettingsScreen) })
                                .align(Alignment.CenterHorizontally)
                                .padding(PixelDensity.SMALL),
                            text = "Settings",
                            style = MaterialTheme.typography.bodyLarge,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            leadingContent = { Icon(TablerIcons.Settings, null) }
                        )
                    }
                }
                HorizontalDivider()
                if (isSignIn) {
                    HorizontalTextIcon(
                        modifier = navModifier(ScreenType.SETTINGS)
                            .fillMaxWidth()
                            .clickable(onClick = {
                                CoroutineScope(Dispatchers.Default).launch {
                                    ApiActions.logOut()
                                    rootNavigator.replace(DashBoardScreen)
                                }
                            })
                            .padding(PixelDensity.SMALL),
                        text = "Sign Out",
                        style = MaterialTheme.typography.bodyLarge,
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                        leadingContent = { Icon(TablerIcons.Settings, null) }
                    )
                } else {
                    HorizontalTextIcon(
                        modifier = navModifier(ScreenType.SETTINGS)
                            .fillMaxWidth()
                            .clickable(onClick = { rootNavigator.push(AuthScreen) })
                            .padding(PixelDensity.SMALL),
                        text = "Sign In / Register",
                        style = MaterialTheme.typography.bodyLarge,
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                        leadingContent = { Icon(TablerIcons.Settings, null) }
                    )
                }
            }
        }
        VerticalDivider()
        content()
    }
}

@Composable
fun SideDrawerBarPortrait(
    modifier: Modifier,
    imagUrlString: String,
    currentScreenType: ScreenType,
    isSignIn: Boolean,
    content: @Composable () -> Unit,
) {
    val drawerState = rememberDrawerState(DrawerValue.Closed)
    val scope = rememberCoroutineScope()
    val navigator = LocalNavigator.currentOrThrow
    val rootNavigator = remember(navigator) {
        var n = navigator
        while (n.parent != null) n = n.parent!!
        n
    }

    @Composable
    fun navModifier(type: ScreenType) =
        if (currentScreenType == type) {
            Modifier
                .padding(PixelDensity.VERY_SMALL)
                .outline()
        } else {
            Modifier.padding(PixelDensity.VERY_SMALL)
        }
    ModalNavigationDrawer(
        drawerState = drawerState,
        drawerContent = {
            ModalDrawerSheet(
                modifier = modifier,
                drawerContainerColor = MaterialTheme.colorScheme.tertiary, // 👈 background
                drawerContentColor = MaterialTheme.colorScheme.onTertiary,
                content = {
                    Column(
                        modifier = Modifier.weight(1f).verticalScrollable(),
                        verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                    ) {
                        VerticalTextIcon(
                            modifier = Modifier
                                .padding(horizontal = PixelDensity.MEDIUM)
                                .clickable(onClick = { scope.launch { drawerState.close() } }),
                            leadingContent = {
                                SubcomposeAsyncImage(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(PixelDensity.getPixelDensity(200))
                                        .clickable(onClick = { scope.launch { drawerState.close() } })
                                        .clip(MaterialTheme.shapes.medium),
                                    model = imagUrlString,//use profile image
                                    contentDescription = "profile image",
                                    loading = {
                                        DisplayLottie(
                                            modifier = Modifier,
                                            lottiePath = "files/avatar.json"
                                        )
                                    },
                                    error = {
                                        DisplayLottie(
                                            modifier = Modifier,
                                            lottiePath = "files/avatar.json"
                                        )
                                    },
                                )
                            },
                            text = "KimDeo AI",
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            style = MaterialTheme.typography.headlineSmall
                        )
                        HorizontalDivider()
                        HorizontalTextIcon(
                            modifier = navModifier(ScreenType.DASHBOARD)
                                .fillMaxWidth()
                                .clickable(onClick = { rootNavigator.replace(DashBoardScreen) })
                                .align(Alignment.CenterHorizontally)
                                .padding(PixelDensity.SMALL),
                            text = "Dashboard",
                            style = MaterialTheme.typography.bodyLarge,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            leadingContent = { Icon(TablerIcons.SmartHome, null) }
                        )
                        if (isSignIn) {
                            HorizontalTextIcon(
                                modifier = navModifier(ScreenType.PROFILE)
                                    .fillMaxWidth()
                                    .clickable(onClick = { rootNavigator.replace(ProfileUserScreen) })
                                    .align(Alignment.CenterHorizontally)
                                    .padding(PixelDensity.SMALL),
                                text = "Profile",
                                style = MaterialTheme.typography.bodyLarge,
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                                leadingContent = { Icon(TablerIcons.UserX, null) }
                            )
                        }
                        HorizontalTextIcon(
                            modifier = navModifier(ScreenType.VIDEO_PLAYER)
                                .fillMaxWidth()
                                .clickable(onClick = { rootNavigator.replace(BaseVideoPlayer()) })
                                .align(Alignment.CenterHorizontally)
                                .padding(PixelDensity.SMALL),
                            text = "Video Player",
                            style = MaterialTheme.typography.bodyLarge,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            leadingContent = { Icon(TablerIcons.Video, null) }
                        )
                        HorizontalTextIcon(
                            modifier = navModifier(ScreenType.TRANSCRIBING)
                                .fillMaxWidth()
                                .clickable(onClick = { rootNavigator.replace(TranscribeScreen()) })
                                .align(Alignment.CenterHorizontally)
                                .padding(PixelDensity.SMALL),
                            text = "Transcribing",
                            style = MaterialTheme.typography.bodyLarge,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            leadingContent = { Icon(TablerIcons.Settings, null) }
                        )
                        if (isSignIn) {
                            HorizontalTextIcon(
                                modifier = navModifier(ScreenType.SETTINGS)
                                    .fillMaxWidth()
                                    .clickable(onClick = { rootNavigator.replace(UserSettingsScreen) })
                                    .align(Alignment.CenterHorizontally)
                                    .padding(PixelDensity.SMALL),
                                text = "Settings",
                                style = MaterialTheme.typography.bodyLarge,
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                                leadingContent = { Icon(TablerIcons.Settings, null) }
                            )
                        }
                    }
                    HorizontalDivider()
                    if (isSignIn) {
                        HorizontalTextIcon(
                            modifier = navModifier(ScreenType.SETTINGS)
                                .fillMaxWidth()
                                .clickable(onClick = {
                                    scope.launch {
                                        ApiActions.logOut()
                                        rootNavigator.replace(DashBoardScreen)
                                    }
                                })
                                .padding(PixelDensity.SMALL),
                            text = "Sign Out",
                            style = MaterialTheme.typography.bodyLarge,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            leadingContent = { Icon(TablerIcons.Settings, null) }
                        )
                    } else {
                        HorizontalTextIcon(
                            modifier = navModifier(ScreenType.SETTINGS)
                                .fillMaxWidth()
                                .clickable(onClick = { rootNavigator.push(AuthScreen) })
                                .padding(PixelDensity.SMALL),
                            text = "Sign In / Register",
                            style = MaterialTheme.typography.bodyLarge,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                            leadingContent = { Icon(TablerIcons.Settings, null) }
                        )
                    }
                }
            )
        },
        content = {
            Column {
                HorizontalTextIcon(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(
                            color = MaterialTheme.colorScheme.tertiary,
                            shape = MaterialTheme.shapes.small
                        )
                        .padding(PixelDensity.SMALL),
                    leadingContent = {
                        IconButton(onClick = { scope.launch { drawerState.open() } }, content = {
                            Icon(
                                if (drawerState.isOpen) TablerIcons.Menu else TablerIcons.Menu2,
                                null,
                                tint = MaterialTheme.colorScheme.onTertiary
                            )
                        })
                    },
                    text = "Kimdeo AI",
                    style = MaterialTheme.typography.headlineSmall.copy(color = MaterialTheme.colorScheme.onTertiary)
                )
                content()
            }
        }
    )
}


@Composable
fun DisplayLottie(
    modifier: Modifier,
    lottiePath: String
) {
    val composition by rememberLottieComposition {
        LottieCompositionSpec.JsonString(
            Res.readBytes(lottiePath).decodeToString()
        )
    }
    val progress by animateLottieCompositionAsState(
        composition,
        iterations = Compottie.IterateForever
    )
    if (composition != null) {
        Image(
            modifier = modifier,
            painter = rememberLottiePainter(
                composition = composition,
                progress = { progress },
            ),
            contentDescription = "Lottie animation"
        )
    } else {
        Box(modifier, contentAlignment = Alignment.Center) {
            PulsingRing()
        }
    }
}