package api.auth.kimdeo.screens.video_player

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import api.auth.kimdeo.screens.video_player.VideoPlayerSelectingScreen.LandScapeDisplay
import api.auth.kimdeo.screens.video_player.VideoPlayerSelectingScreen.PortraitDisplay
import api.auth.kimdeo.utils.Orientation
import api.auth.kimdeo.utils.rememberDeviceInfo

@Composable
fun SelectVideoPlayerFree(modifier: Modifier) {
    val deviceInfo = rememberDeviceInfo()
    when (deviceInfo.orientation) {
        Orientation.PORTRAIT -> PortraitDisplay(
            modifier = modifier,
            deviceInfo = deviceInfo
        )

        else -> LandScapeDisplay(
            modifier = modifier,
            deviceInfo = deviceInfo
        )
    }
}

