private typealias InfoDisplay = PopupModel

private val infoDisplay = listOf(
    InfoDisplay(
        show = true,
        title = "Fast & Accurate",
        description = "An AI that works with high accuracy",
        content = { Icon(TablerIcons.Speedboat, null, tint = SkyBlue) }
    ),
    InfoDisplay(
        show = true,
        title = "AI Transcription",
        description = "Experience fast and high media transcription, design to save you valuable time",
        content = { Icon(TablerIcons.DeviceAnalytics, null, tint = LeaveGreen) }
    ),
    InfoDisplay(
        show = true,
        title = "AI Translation",
        description = "Deliver highly accurate and natural sounding translations, across multiple language",
        content = { Icon(TablerIcons.Language, null, tint = Purple) }
    ),
    InfoDisplay(
        show = true,
        title = "AI Dubbing",
        description = "Add voice over to your media to make it sound more natural",
        content = { Icon(TablerIcons.Language, null, tint = WoodBrown) }
    ),
)

object DashBoardScreen : Screen {
    @Composable
    override fun Content() {
        val deviceInfo = rememberDeviceInfo()
        val screenModel = rememberScreenModel { DashBoardScreenModel() }
        LaunchedEffect(Unit, block = {screenModel.initialiseDashboard()})
        Scaffold { pv ->
            DashBoardPopup(screenModel)
            when (screenModel.connectionState) {
                is ConnectionState.OnFailure -> {
                    when (deviceInfo.orientation) {
                        Orientation.PORTRAIT -> PortraitDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize(),
                            deviceInfo = deviceInfo
                        )

                        else -> LandScapeDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize()
                                .padding(PixelDensity.MEDIUM),
                            deviceInfo = deviceInfo
                        )
                    }
                }

                is ConnectionState.OnSucsess -> {
                    when (deviceInfo.orientation) {
                        Orientation.PORTRAIT -> PortraitDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize(),
                            deviceInfo = deviceInfo
                        )

                        else -> LandScapeDisplay(
                            modifier = Modifier
                                .padding(pv)
                                .fillMaxSize()
                                .padding(PixelDensity.MEDIUM),
                            deviceInfo = deviceInfo
                        )
                    }
                }

                else -> {
                    Column(
                        Modifier.fillMaxSize().padding(pv),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        val pulseBeforeShow = remember { mutableStateOf(false) }

                        LaunchedEffect(pulseBeforeShow) {
                            if (!pulseBeforeShow.value) {
                                delay(5000.milliseconds)
                                pulseBeforeShow.value = true
                            }
                        }
                        PulsingRing()
                        if (pulseBeforeShow.value) {
                            ShimmeringText(
                                "Loading... seems to be taking a lot of time.",
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                            )
                            ReloadButton(
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                                onReload = {
                                    pulseBeforeShow.value = false
                                },
                                onGoBack = null
                            )
                        }

                    }
                }
            }
        }
    }

    @Composable
    private fun PortraitDisplay(deviceInfo: DeviceInfo, modifier: Modifier) {
        val screenModel = rememberScreenModel { DashBoardScreenModel() }
        SideDrawerBarPortrait(
            modifier = Modifier
                .width(PixelDensity.getPixelDensity(deviceInfo.width.toPercentage(70)))
                .fillMaxHeight(),
            imagUrlString = screenModel.userModel?.imagePath ?: "",
            isSignIn = screenModel.userModel != null,
            currentScreenType = ScreenType.DASHBOARD,
            content = {
                BodyContent(
                    modifier = modifier
                        .verticalScrollable(),
                    width = deviceInfo.width
                )
            }
        )
    }

    @Composable
    private fun LandScapeDisplay(deviceInfo: DeviceInfo, modifier: Modifier) {
        val screenModel = rememberScreenModel { DashBoardScreenModel() }
        SideDrawerBarLandscape(
            imagUrlString = screenModel.userModel?.imagePath ?: "",
            currentScreenType = ScreenType.DASHBOARD,
            drawerModifier = Modifier
                .width(PixelDensity.getPixelDensity(deviceInfo.width.toPercentage(20)))
                .fillMaxHeight(),
            modifier = modifier,
            isSignIn = screenModel.userModel != null,
            content = {
                BodyContent(
                    modifier = Modifier.weight(0.8f).verticalScrollable(),
                    width = deviceInfo.width.toPercentage(80).toInt()
                )

            }
        )
    }

    @Composable
    private fun BodyContent(modifier: Modifier, width: Int) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Row(
                Modifier.width(PixelDensity.getPixelDensity(width)).horizontalScrollable(),
                horizontalArrangement = Arrangement.Center,
            ) {
                infoDisplay.forEach { info ->
                    DisplayInfo(
                        Modifier
                            .width(PixelDensity.getPixelDensity(200))
                            .height(PixelDensity.getPixelDensity(100))
                            .padding(PixelDensity.MEDIUM),
                        info
                    )
                }
            }

            DisplayLottie(
                modifier = Modifier.height(PixelDensity.getPixelDensity(200)),
                lottiePath = "files/translate_lottie.json"
            )
            FlowRow(
                Modifier.fillMaxWidth().fillMaxHeight(),
                verticalArrangement = Arrangement.Center,
                horizontalArrangement = Arrangement.Center,
                itemVerticalAlignment = Alignment.CenterVertically
            ) {
                Column(
                    Modifier
                        .padding(PixelDensity.MEDIUM)
                        .width(PixelDensity.getPixelDensity(400)),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = "Break language barrier ",
                        style = MaterialTheme.typography.bodyLarge.copy(
                            color = MaterialTheme.colorScheme.primary
                        )
                    )
                    Text(
                        text = "Experience the power of AI dubbing, transcribing and translating that works seamlessly",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            textAlign = TextAlign.Center,
                            color = MaterialTheme.colorScheme.secondary
                        )
                    )
                }
                Column(
                    Modifier
                        .padding(PixelDensity.MEDIUM)
                        .width(PixelDensity.getPixelDensity(400)),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = "Video player for everyone ",
                        style = MaterialTheme.typography.bodyLarge.copy(
                            color = MaterialTheme.colorScheme.primary
                        )
                    )
                    Text(
                        text = "Leverage AI-powered video analysis to instantly understand what any video is about. Extract valuable information and transform your videos through powerful customization tools.",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            color = MaterialTheme.colorScheme.secondary,
                            textAlign = TextAlign.Center
                        )
                    )
                }
            }
        }
    }

    @Composable
    private fun DisplayInfo(
        modifier: Modifier,
        infoDisplay: InfoDisplay
    ) {
        Surface(
            modifier = Modifier.padding(PixelDensity.MEDIUM),
            shape = MaterialTheme.shapes.medium,
            color = MaterialTheme.colorScheme.secondary.copy(alpha = 0.2f),
            contentColor = MaterialTheme.colorScheme.onBackground,
            shadowElevation = PixelDensity.VERY_SMALL,
            border = BorderStroke(
                PixelDensity.VERY_SMALL,
                color = MaterialTheme.colorScheme.background
            )
        ) {
            Column(modifier = modifier) {
                HorizontalTextIcon(
                    leadingContent = { infoDisplay.content() },
                    text = infoDisplay.title,
                    style = MaterialTheme.typography.bodyLarge
                )
                Text(infoDisplay.description, style = MaterialTheme.typography.bodyMedium)
            }
        }
    }


    @Composable
    private fun DashBoardPopup(screenModel: DashBoardScreenModel) {
        DisplayPopup(
            show = screenModel.dashBoardPopup.show,
            onDismiss = {
                if (screenModel.dashBoardPopup.isDismissible) {
                    screenModel.dashBoardPopup = PopupModel()
                }
            },
            content = {
                Column(
                    Modifier.outline().padding(PixelDensity.MEDIUM).background(
                        shape = MaterialTheme.shapes.medium,
                        color = MaterialTheme.colorScheme.background
                    ),
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                ) {
                    HorizontalTextIcon(
                        leadingContent = { screenModel.dashBoardPopup.content() },
                        text = screenModel.dashBoardPopup.title,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                    )
                    Text(
                        text = screenModel.dashBoardPopup.description,
                        style = MaterialTheme.typography.bodyMedium
                    )
                }

            }
        )
    }

}
