package api.auth.kimdeo.core.api

import api.auth.kimdeo.createHttpClient
import api.auth.kimdeo.model.FilePathModel
import api.auth.kimdeo.model.GenerateVoiceWVIPModel
import api.auth.kimdeo.model.GenerateVoiceWVIPModelFree
import api.auth.kimdeo.model.JobMessage
import api.auth.kimdeo.model.JobStatus
import api.auth.kimdeo.model.TranscribeJobModel
import api.auth.kimdeo.model.WebSocketJobModel
import co.touchlab.kermit.Logger
import io.ktor.client.plugins.websocket.webSocket
import io.ktor.websocket.CloseReason
import io.ktor.websocket.Frame
import io.ktor.websocket.close
import io.ktor.websocket.readText
import kotlinx.serialization.json.Json
import kotlin.coroutines.cancellation.CancellationException

object ApiActionsWebsocket {


    private val kimJson = Json {
        prettyPrint = true
        isLenient = true
        classDiscriminator = "type"
        ignoreUnknownKeys = true
        explicitNulls = false
    }
    private val apiClient = createHttpClient()

    suspend fun connectToPlayingVideoWebsocket(
        genVoice: GenerateVoiceWVIPModel,
        jobId: String?,
        userApikey: String?,
        onConnect: suspend (FilePathModel?) -> Unit,
    ) {
        if (jobId == null || userApikey == null) return

        try {
            apiClient.webSocket(
                urlString = "${WS_API_ROOT_PATH}/ws/video_playing_job/$jobId?token=$userApikey"
            ) {
                send(Frame.Text(kimJson.encodeToString(genVoice)))

                val frame = incoming.receive() as? Frame.Text ?: return@webSocket

                val result =
                    kimJson.decodeFromString<WebSocketJobModel<FilePathModel>>(frame.readText())
                onConnect(result.dataType)
            }
        } catch (e: CancellationException) {
            Logger.e("connectToPlayingVideoWebsocket WebSocket CancellationException: ${e.message}")
            throw e
        } catch (e: Exception) {
            Logger.e("connectToPlayingVideoWebsocket WebSocket error: ${e.message}")
        }
    }

    suspend fun connectToPlayingVideoWebsocketFree(
        genVoice: GenerateVoiceWVIPModelFree,
        onConnect: suspend (WebSocketJobModel<FilePathModel?>) -> Unit,
    ) {
        try {
            apiClient.webSocket(
                urlString = "${WS_API_ROOT_PATH}/ws/playground_video_playing"
            ) {
                send(Frame.Text(kimJson.encodeToString(genVoice)))

                val frame = incoming.receive() as? Frame.Text ?: return@webSocket

                val result =
                    kimJson.decodeFromString<WebSocketJobModel<FilePathModel?>>(frame.readText())
                onConnect(result)
            }
        } catch (e: CancellationException) {
            Logger.e("connectToPlayingVideoWebsocket WebSocket CancellationException: ${e.message}")
            throw e
        } catch (e: Exception) {
            Logger.e("connectToPlayingVideoWebsocket WebSocket error: ${e.message}")
        }
    }

    suspend fun connectToPlayerWebsocket(
        jobId: String,
        userApikey: String,
        onConnect: (TranscribeJobModel) -> Unit,
    ) {
        apiClient.webSocket(
            urlString = "${WS_API_ROOT_PATH}/ws/player_job/$jobId?token=$userApikey"
        ) {
            try {
                for (frame in incoming) {
                    when (frame) {

                        is Frame.Text -> {
                            val text = frame.readText()

                            val job = kimJson.decodeFromString<TranscribeJobModel>(text)
                            try {
                                onConnect(job)
                            } catch (e: Exception) {
                                Logger.e("Callback error: ${e.message}")
                            }

                            if (
                                job.jobStatus == JobStatus.COMPLETED ||
                                job.jobStatus == JobStatus.FAILED
                            ) {

                                val reason = when (job.jobStatus) {
                                    JobStatus.COMPLETED -> "Job completed"
                                    JobStatus.FAILED -> "Job failed"
                                }

                                close(
                                    CloseReason(
                                        CloseReason.Codes.NORMAL,
                                        reason
                                    )
                                )

                                break
                            }
                        }

                        is Frame.Close -> {
                            Logger.d("WebSocket closed")
                        }

                        else -> Unit
                    }
                }
            } catch (e: CancellationException) {
                Logger.e("connectToPlayerWebsocket WebSocket CancellationException: ${e.message}")
                throw e
            } catch (e: Exception) {
                Logger.e("connectToPlayerWebsocket WebSocket error: ${e.message}")
            }
        }
    }


    suspend fun connectToWebsocket(
        jobId: String,
        userApikey: String,
        onConnect: (TranscribeJobModel) -> Unit,
    ) {
        apiClient.webSocket(
            urlString = "${WS_API_ROOT_PATH}/ws/job/$jobId?token=$userApikey",
            block = {
                try {
                    for (frame in incoming) {
                        when (frame) {
                            is Frame.Text -> {
                                val text = frame.readText()
                                // Deserialize if needed
                                val job = kimJson.decodeFromString<TranscribeJobModel>(text)
                                onConnect(job)
                            }

                            is Frame.Close -> Unit

                            else -> {}
                        }
                    }
                } catch (e: Exception) {
                    Logger.e("connectToWebsocket WebSocket error: ${e.message}")
                }
            }
        )
    }

    suspend fun connectToWebsocketUserId(
        userId: String,
        userApikey: String,
        onConnect: (JobMessage) -> Unit,
    ) {
        apiClient.webSocket(
            urlString = "${WS_API_ROOT_PATH}/ws/user/$userId?token=$userApikey",
            block = {
                try {
                    for (frame in incoming) {
                        when (frame) {
                            is Frame.Text -> {
                                val text = frame.readText()
                                // Deserialize if needed
                                val message = kimJson.decodeFromString<JobMessage>(text)
                                onConnect(message)
                            }

                            is Frame.Close -> Unit

                            else -> Unit
                        }
                    }
                } catch (e: Exception) {
                    println("connectToWebsocketUserId WebSocket error: ${e.message}")
                }
            }

        )
    }


    suspend fun uploadToPlayGroundWebSocket(
        jobId: String,
        onConnect: (WebSocketJobModel<FilePathModel?>) -> Unit,
    ) {
        apiClient.webSocket(
            urlString = "${WS_API_ROOT_PATH}/ws/playground/$jobId",
            block = {
                try {
                    for (frame in incoming) {
                        when (frame) {
                            is Frame.Text -> {
                                val text = frame.readText()
                                // Deserialize if needed
                                val message =
                                    kimJson.decodeFromString<WebSocketJobModel<FilePathModel?>>(text)
                                onConnect(message)
//                                if (message.jobStatus == JobStatus.COMPLETED) close()
                            }

                            is Frame.Close -> Unit

                            else -> Unit
                        }
                    }
                } catch (e: Exception) {
                    close()
                    Logger.e("uploadToPlayGroundWebSocket error: ${e.printStackTrace()}")
                }
            }

        )
    }
}