package api.auth.kimdeo.utils


class AuthenticationException(message: String) : Exception(message)


fun cleanError(errorMessage: String?, defaultMessage: String): String {
    if (errorMessage.isNullOrBlank()) return defaultMessage

    return if (
        errorMessage.contains("Client request(") ||
        errorMessage.contains("Server error(") ||
        errorMessage.contains("http://") ||
        errorMessage.contains("https://")
    ) {
        defaultMessage
    } else {
        errorMessage
    }
}