object VideoPlayerSelectingScreen : Screen {
    @Composable
    override fun Content() {
        val navigator = LocalNavigator.currentOrThrow
        val screenModel = navigator.rememberNavigatorScreenModel { VideoPlayerScreenModel() }
        Scaffold { pv ->
            VideoPlayerPopup(screenModel)
            when (screenModel.connectionState) {
                is ConnectionState.OnFailure -> {
                    SelectVideoPlayerFree(modifier = Modifier.fillMaxSize().padding(pv))
                }

                is ConnectionState.OnSucsess -> {
                     SelectVideoPlayerFree(
                        modifier = Modifier.fillMaxSize().padding(pv)
                    )
                }

                else -> {
                    Column(
                        Modifier.fillMaxSize().padding(pv),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        val pulseBeforeShow = remember { mutableStateOf(false) }

                        LaunchedEffect(pulseBeforeShow) {
                            if (!pulseBeforeShow.value) {
                                delay(5000.milliseconds)
                                pulseBeforeShow.value = true
                            }
                        }
                        PulsingRing()
                        if (pulseBeforeShow.value) {
                            ShimmeringText(
                                "Loading... seems to be taking a lot of time.",
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                            )
                            ReloadButton(
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                                onReload = {
                                    screenModel.resetScreenModel()
                                    pulseBeforeShow.value = false
                                },
                                onGoBack = { navigator.replace(DashBoardScreen)}
                            )
                        }

                    }
                }
            }
        }
    }

    @Composable
    private fun VideoPlayerPopup(screenModel: VideoPlayerScreenModel) {
        DisplayPopup(
            show = screenModel.playGroundPopup.show,
            onDismiss = {
                if (screenModel.playGroundPopup.isDismissible) {
                    screenModel.playGroundPopup = PopupModel()
                }
            },
            content = {
                Column(
                    Modifier.outline().padding(PixelDensity.MEDIUM).background(
                        shape = MaterialTheme.shapes.medium,
                        color = MaterialTheme.colorScheme.background
                    ),
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                ) {
                    HorizontalTextIcon(
                        leadingContent = { screenModel.playGroundPopup.content() },
                        text = screenModel.playGroundPopup.title,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                    )
                    Text(
                        text = screenModel.playGroundPopup.description,
                        style = MaterialTheme.typography.bodyMedium
                    )
                }

            }
        )
    }

    @Composable
    internal fun PortraitDisplay(modifier: Modifier, deviceInfo: DeviceInfo) {
        val navigator = LocalNavigator.currentOrThrow
        val screenModel = navigator.rememberNavigatorScreenModel { VideoPlayerScreenModel() }
        Box(contentAlignment = Alignment.BottomCenter) {
            SideDrawerBarPortrait(
                modifier = Modifier
                    .width(PixelDensity.getPixelDensity(deviceInfo.width.toPercentage(70)))
                    .fillMaxHeight(),
                imagUrlString = screenModel.userModel?.imagePath ?: "",
                isSignIn = screenModel.userModel != null,
                currentScreenType = ScreenType.VIDEO_PLAYER,
                content = {
                    BodyContent(
                        modifier = modifier
                            .verticalScrollable()
                    )
                }
            )
            DisplayBottomSheet(
                sheetContent = {
                    TranscriptionProcessOutPut(
                        modifier = Modifier.fillMaxWidth(),
                        screenModel = screenModel
                    )
                },
                anchorContent = {
                    HorizontalDivider(thickness = PixelDensity.MEDIUM)
                }
            )
        }
    }

    @Composable
    internal fun BodyContent(modifier: Modifier) {
        val navigator = LocalNavigator.currentOrThrow
        val screenModel = navigator.rememberNavigatorScreenModel { VideoPlayerScreenModel() }
        val deviceInfo = rememberDeviceInfo()
        val isPortraitModifier = remember {
            derivedStateOf {
                if (deviceInfo.orientation == Orientation.PORTRAIT) {
                    Modifier
                        .padding(PixelDensity.MEDIUM)
                        .fillMaxWidth()
                        .height(PixelDensity.getPixelDensity(300))
                } else {
                    Modifier
                        .padding(PixelDensity.MEDIUM)
                        .width(
                            PixelDensity.getPixelDensity(
                                deviceInfo.width.toPercentage(30)
                            )
                        )
                        .height(PixelDensity.getPixelDensity(300))
                }
            }
        }
        Column(modifier = modifier) {
            FlowRow(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.Center,
                maxItemsInEachRow = 2
            ) {
                PickFileDisplay(
                    modifier = isPortraitModifier.value,
                    screenModel
                )
                TranscribeFileDisplay(
                    modifier = isPortraitModifier.value,
                    screenModel = screenModel,
                    navigator = navigator
                )
            }
            if (deviceInfo.orientation != Orientation.PORTRAIT) {
//                DisplayBottomSheet(
//                    sheetContent = {
//                        TranscriptionProcessOutPut(
//                            modifier = Modifier.fillMaxWidth(),
//                            screenModel = screenModel
//                        )
//                    },
//                    anchorContent = {
//                        HorizontalDivider(thickness = PixelDensity.MEDIUM)
//                    }
//                )
                TranscriptionProcessOutPut(
                    modifier = Modifier.fillMaxWidth(),
                    screenModel = screenModel
                )
            }
        }
    }

    @Composable
    internal fun PickFileDisplay(modifier: Modifier, screenModel: VideoPlayerScreenModel) {
        Surface(Modifier.padding(PixelDensity.MEDIUM)) {
            Column(
                modifier = modifier,
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center
            ) {
                Box(
                    Modifier
                        .outline()
                        .clickable(
                            enabled = screenModel.enableButton,
                            onClick = { screenModel.getMediaFileFree() })
                        .padding(
                            horizontal = PixelDensity.MEDIUM,
                            vertical = PixelDensity.LARGE
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    var thumbnail by remember {
                        mutableStateOf<String?>(null)
                    }
                    if (screenModel.platformFile == null) {
                        DisplayLottie(
                            modifier = Modifier.height(PixelDensity.getPixelDensity(170)),
                            lottiePath = "files/file_picker.json"
                        )
                    } else {
                        LaunchedEffect(screenModel.platformFile) {
                            screenModel.platformFile?.let { pf ->
                                thumbnail = generateThumbnail(
                                    bytes = pf.readBytes(),
                                    mimeType = screenModel.platformFile?.mimeType()?.toString()
                                        ?: "video/mp4"
                                )
                            }
                        }
                        if (thumbnail != null) {
                            SubcomposeAsyncImage(
                                modifier = Modifier.height(PixelDensity.getPixelDensity(170)),
                                model = thumbnail,
                                contentDescription = "video thumbnail",
                                loading = {}
                            )
                        }
                    }

                }
                Text(
                    screenModel.platformFile?.name ?: "",
                    textAlign = TextAlign.Center,
                    style = MaterialTheme.typography.bodyMedium
                )
                HorizontalDivider()
                StyledText(
                    contents = listOf(
                        ComTextModel(
                            text = "You can click and select any video file ",
                            style = MaterialTheme.typography.bodyMedium.toSpanStyle()
                        ),
                        ComTextModel(
                            text = "Supported formats: ",
                            style = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.primary)
                                .toSpanStyle()
                        ),
                        ComTextModel(
                            text = ExportVideoFormat.entries.joinToString(", ") { it.name.lowercase() },
                            style = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.secondary)
                                .toSpanStyle()
                        ),
                    )
                )
            }
        }
    }

    @Composable
    internal fun TranscribeFileDisplay(
        modifier: Modifier,
        screenModel: VideoPlayerScreenModel,
        navigator: Navigator
    ) {
        Surface(Modifier.padding(PixelDensity.MEDIUM)) {
            Column(
                modifier = modifier,
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center
            ) {
                var selectedKimLanguage by remember { mutableStateOf("") }
                var expandLanguage by remember { mutableStateOf(false) }
                Text(
                    text = "Configure Video",
                    style = MaterialTheme.typography.bodyLarge
                )
                OutlinedButton(
                    modifier = Modifier.fillMaxWidth(),
                    enabled = (screenModel.platformFile != null) && screenModel.enableButton,
                    onClick = { expandLanguage = !expandLanguage },
                    content = {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            StyledText(
                                contents = listOf(
                                    ComTextModel(
                                        text = "Select Language ",
                                        style = MaterialTheme.typography.bodyMedium.toSpanStyle()
                                    ),
                                    ComTextModel(
                                        text = "(${screenModel.kimLanguage})",
                                        style = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.primary)
                                            .toSpanStyle()
                                    )
                                )
                            )
                            Icon(
                                if (expandLanguage) TablerIcons.ChevronUp else TablerIcons.ChevronDown,
                                contentDescription = "expand languages"
                            )
                        }
                    })

                AnimatedVisibility(expandLanguage, content = {
                    SelectLanguages(
                        selectedKimLanguage,
                        kimLanguage = screenModel.kimLanguage,
                        kimLanguages = screenModel.kimLanguages,
                        onLangNalChanged = {
                            selectedKimLanguage = it
                            screenModel.checkKimLanguages(it)
                        },
                        onClear = {
                            selectedKimLanguage = ""
                            screenModel.checkKimLanguages("")
                        },
                        onSelect = {
                            screenModel.kimLanguage = it
                            expandLanguage = !expandLanguage
                        }
                    )
                })

                OutlinedButton(
                    modifier = Modifier.fillMaxWidth(),
                    enabled = (screenModel.platformFile != null) && screenModel.enableButton,
                    onClick = { screenModel.transcribeVideoFree() },
                    content = {
                        HorizontalTextIcon(
                            leadingContent = { Icon(TablerIcons.Stars, null) },
                            text = "Transcribe Video",
                            style = MaterialTheme.typography.bodyMedium
                        )
                    })

                OutlinedButton(
                    modifier = Modifier.fillMaxWidth(),
                    enabled = (screenModel.platformFile != null) && screenModel.enableButton,
                    onClick = {
                        navigator.push(VideoPlayerPlayingScreen)
                    },
                    content = {
                        HorizontalTextIcon(
                            leadingContent = { Icon(TablerIcons.Video, null) },
                            text = "Watch Video",
                            style = MaterialTheme.typography.bodyMedium
                        )
                    })

            }
        }
    }

    @Composable
    internal fun TranscriptionProcessOutPut(
        modifier: Modifier,
        screenModel: VideoPlayerScreenModel
    ) {
        Surface(
            shape = MaterialTheme.shapes.small,
            tonalElevation = PixelDensity.VERY_SMALL,
            shadowElevation = PixelDensity.VERY_SMALL
        ) {
            Column(
                modifier,
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
            ) {
                Text(
                    "Transcription / Translation output",
                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                )
                AnimatedVisibility(
                    screenModel.transcribeProcess.second.isNotEmpty(),
                    content = {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Box(
                                Modifier.background(MaterialTheme.colorScheme.primaryContainer),
                                contentAlignment = Alignment.Center
                            ) {
                                Box(
                                    modifier = Modifier.fillMaxWidth()
                                        .shimmerProgress(
                                            speed = 2000,
                                            colors = listOf(
                                                MaterialTheme.colorScheme.primary,
                                                MaterialTheme.colorScheme.secondary
                                            ),
                                            progress = screenModel.transcribeProcess.first / 100,
                                            backgroundColor = MaterialTheme.colorScheme.primary.copy(
                                                alpha = 0.5f
                                            )
                                        ).padding(PixelDensity.LARGE),
                                )
                                Text(
                                    text = screenModel.transcribeProcess.second,
                                    style = MaterialTheme.typography.bodyMedium.copy(
                                        textAlign = TextAlign.Center,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.background
                                    )
                                )
                            }
                        }
                    }
                )
            }
        }
    }

    @Composable
    internal fun LandScapeDisplay(modifier: Modifier, deviceInfo: DeviceInfo) {
        val navigator = LocalNavigator.currentOrThrow
        // Reuses the same instance
        val screenModel = navigator.rememberNavigatorScreenModel { VideoPlayerScreenModel() }

        SideDrawerBarLandscape(
            imagUrlString = screenModel.userModel?.imagePath ?: "",
            currentScreenType = ScreenType.VIDEO_PLAYER,
            drawerModifier = Modifier
                .width(PixelDensity.getPixelDensity(deviceInfo.width.toPercentage(20)))
                .fillMaxHeight(),
            modifier = modifier,
            isSignIn = screenModel.userModel != null,
            content = {
                BodyContent(
                    modifier = Modifier.weight(0.8f).padding(PixelDensity.SMALL)
                        .verticalScrollable()
                )
            }
        )

    }

