enum class ProfilePopupType {
    SHOW_SUBSCRIBE,
    SHOW_MESSAGE,
    NONE,
}

class ProfileScreenModel : ScreenModel {

    var userModel by mutableStateOf<UserModel?>(null)
    var profileImage by mutableStateOf<ByteArray?>(null)
        private set
    var popupMessage by mutableStateOf(PopupModel())

    var profilePopup by mutableStateOf(ProfilePopupType.NONE)
    private val fileSaver = KimDeoFile()
    var pagerLimit by mutableIntStateOf(5)
    var subscriptionModel by mutableStateOf<SubscriptionModel?>(null)
    private val _allJobs = mutableStateListOf<TranscribeJobModel>()
    val allJobs: List<TranscribeJobModel> get() = _allJobs
    var connectionState by mutableStateOf<ConnectionState>(ConnectionState.None)
    var showProfileDetails by mutableStateOf(true)
//    var transcription by mutableStateOf<Transcription?>(null)

    init { initialiseScreenModel() }

    fun initialiseScreenModel() {
        connectionState = ConnectionState.OnLoading
        screenModelScope.launch {
            val userToken = PreferenceManager.getUserToken()
            if (userToken == null) {
                connectionState =
                    ConnectionState.OnFailure("You are not logged in, please login to continue")
            } else {
                val u = ApiActions.getUserModelByEmail(
                    LogInModel(
                        userToken.email,
                        userToken.password
                    )
                )
                Logger.e { "error => $u" }
                if (u.data == null) {
                    connectionState =
                        ConnectionState.OnFailure("Could not get your details, please try logging in to continue")
                    return@launch
                }
                subscriptionModel = ApiActions.getCredits(
                    LogInModel(
                        u.data.userId,
                        u.data.password
                    )
                ).data
                connectionState = ConnectionState.OnSucsess("")
                userModel = u.data
                profileImage = ApiActionsFile.loadFile(
                    LoadFileRequest(
                        userModel?.imagePath ?: "",
                        LogInModel(
                            userModel?.userId ?: "",
                            userModel?.password ?: ""
                        )
                    )
                )
                while (screenModelScope.isActive) {
                    try {
                        ApiActionsWebsocket.connectToWebsocketUserId(
                            u.data.userId,
                            u.data.apiKey,
                            { jobMessage ->
                                when (jobMessage) {
                                    is JobMessage.Initial -> {
                                        _allJobs.apply {
                                            clear()
                                            addAll(jobMessage.jobs.sortedByDescending { it.createdAt })
                                        }

                                    }

                                    is JobMessage.Update -> {
                                        _allJobs.replaceAllWhere { if (it.transcriptionId == jobMessage.job.transcriptionId) jobMessage.job else it }
                                    }
                                }
                            })
                        delay(3000)
                    } catch (e: Exception) {
                        delay(3000) // retry
                    }
                }
            }
        }
    }

    fun showProfilePopup(profilePopupType: ProfilePopupType, popupModel: PopupModel? = null) {
        profilePopup = profilePopupType
        if (popupModel != null) {
            popupMessage = popupModel
        }
    }

    fun downloadVoiceOver(url: String) {
        screenModelScope.launch {
            runCatching {
                ApiActionsFile.downloadFile(
                    LoadFileRequest(
                        url,
                        LogInModel(
                            userModel!!.email,
                            userModel!!.password
                        )
                    )
                )
            }.onSuccess { bytes ->
                fileSaver.saveBytesDownload(bytes!!, Tools.generateUUID() + ".mp4")
                popupMessage = PopupModel(
                    show = true,
                    title = "Download Video File",
                    description = "Your voice over is downloading.",
                )
            }.onFailure { error ->
                popupMessage = PopupModel(
                    show = true,
                    title = "Error Voice Over",
                    description = cleanError(error.message,"There was an error downloading video File"),
                    content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                )
            }
        }
    }

    fun downloadAudio(url: String) {
        screenModelScope.launch {
            runCatching {
                ApiActionsFile.downloadFile(
                    LoadFileRequest(
                        url,
                        LogInModel(
                            userModel!!.email,
                            userModel!!.password
                        )
                    )
                )
            }.onSuccess { bytes ->
                fileSaver.saveBytesDownload(bytes, Tools.generateUUID() + ".wav")
                popupMessage = PopupModel(
                    show = true,
                    title = "Download Audio File",
                    description = "Your voice over is downloading.",
                )
            }.onFailure { error ->
                popupMessage = PopupModel(
                    show = true,
                    title = "Error Voice Over",
                    description = cleanError(error.message,"There was an error downloading video File"),
                    content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                )
            }
        }
    }

    fun downloadTextFile(url: String) {
        screenModelScope.launch {
            runCatching {
                ApiActionsFile.downloadFile(
                    LoadFileRequest(
                        url,
                        LogInModel(
                            userModel!!.email,
                            userModel!!.password
                        )
                    )
                )
            }.onSuccess { bytes ->
                val jsonString = bytes?.decodeToString()
                if (jsonString == null) {
                    popupMessage = PopupModel(
                        show = true,
                        title = "Error",
                        description = "File was not found"
                    )
                    return@onSuccess
                }
                val srtContent = buildString {
                    val transcription = Json.decodeFromString<Transcription>(jsonString)
                    for ((i, t) in transcription.segments.withIndex()) {
                        append(
                            "$i\n${t.text} \n ${t.start} --> ${t.end}\n\n",
                        )
                    }
                }
                fileSaver.saveBytesDownload(srtContent.toByteArray(), "${Tools.generateUUID()}.srt")
                popupMessage = PopupModel(
                    show = true,
                    title = "Download Audio File",
                    description = "Your voice over is downloading.",
                )
            }.onFailure { error ->
                popupMessage = PopupModel(
                    show = true,
                    title = "Error Voice Over",
                    description = cleanError(error.message,"There was an error downloading video File"),
                    content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                )
            }
        }
    }

    fun deleteJob(jobId: String, filePath: String?) {
        screenModelScope.launch {
            runCatching {
                popupMessage = PopupModel(
                    show = true,
                    title = "Delete Transcription",
                    description = "Deletion in progress please wait...",
                    content = { CircularProgressIndicator() }
                )
                ApiActions.deleteJobByJobId(
                    LogInModel(
                        userModel?.email ?: "",
                        userModel?.password ?: ""
                    ),
                    jobId
                )
            }.onSuccess { suc ->
                _allJobs.removeWhere { it.transcriptionId == jobId }
                _allJobs.sortByDescending { it.createdAt }
                popupMessage = PopupModel(
                    show = true,
                    title = "Delete Transcription",
                    description = suc.message,
                    content = { Icon(TablerIcons.Check, null, tint = Color.Green) }
                )
            }.onFailure { error ->
                popupMessage = PopupModel(
                    show = true,
                    title = "Error",
                    description = cleanError(error.message, "There was an error deleting transcription"),
                    content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                )
            }
        }
    }
}
