package api.auth.kimdeo.core

import dev.whyoleg.cryptography.CryptographyProvider
import dev.whyoleg.cryptography.algorithms.AES
import kotlin.io.encoding.Base64


object CryptoUtils {


    suspend fun encryptData(key: String, value: String): String {
        // 1. Ensure the key is padded/sliced to exactly 32 bytes (256-bit AES)
        val keyBytes = key.encodeToByteArray().copyOf(32)
        val dataBytes = value.encodeToByteArray()

        // 2. Grab the Default Cryptography Provider and create an AES-GCM decoder
        val provider = CryptographyProvider.Default
        val keyDecoder = provider.get(AES.GCM).keyDecoder()

        // 3. Decode your raw bytes into a type-safe symmetric Key object
        val secretKey = keyDecoder.decodeFromByteArray(AES.Key.Format.RAW, keyBytes)

        // 4. Encrypt (Automated Secure IV prepended under the hood)
        val encryptedBytes = secretKey.cipher().encrypt(dataBytes)

        // 5. Safely export as string via Base64
        return Base64.encode(encryptedBytes)
    }

    suspend fun decryptData(key: String, encryptedValue: String): String {
        val keyBytes = key.encodeToByteArray().copyOf(32)
        val encryptedBytes = Base64.decode(encryptedValue)

        val provider = CryptographyProvider.Default
        val keyDecoder = provider.get(AES.GCM).keyDecoder()
        val secretKey = keyDecoder.decodeFromByteArray(AES.Key.Format.RAW, keyBytes)

        // Decrypt (The library unpacks the built-in IV automatically)
        val decryptedBytes = secretKey.cipher().decrypt(encryptedBytes)

        return decryptedBytes.decodeToString()
    }
}



